import re
from taf.selenium.mobile.gnb.oam.coam.classical.facade import Coam, Coam21A
from taf.selenium.mobile.gnb.oam.coam.classical.exceptions import InvalidCoamVersion


class SupportedCoams(object):
    coam = Coam
    coam21a = Coam21A

    @classmethod
    def get_valid_coam_versions(cls):
        coam_versions = []
        for item in cls.__dict__.keys():
            if item.startswith('coam'):
                coam_versions.append(item)
        return coam_versions


class Provider(object):
    @classmethod
    def provide(cls, version=None):
        regex_for_verison = "(?:5[gG])?(.*)?"
        supported_coam = "coam"
        if version:
            version_parsed = re.search(regex_for_verison, version).group(1)
            supported_coam = "coam{version}".format(version=version_parsed.lower())

        try:
            return getattr(SupportedCoams, supported_coam)
        except AttributeError:
            raise InvalidCoamVersion('Supported versions: {}'.format(SupportedCoams.get_valid_coam_versions()))
